-- Ted's Lab Quantum subject, five broad topics, and QuantumPedia imports.
-- This seed intentionally stores original Ted's Lab summaries rather than reproducing source articles.
select (select count(*) from public.subjects where slug='quantum') as quantum_subjects, (select count(*) from public.topics where subject_slug='quantum') as quantum_topics, (select count(*) from public.articles where subject_slug='quantum') as quantum_articles;